select sub.slug, lvl.level::text as level, t.slug as topic, (select count(*) from public.study_materials m where m.topic_id=t.id and m.material_type='notes' and length(m.content)>=1000) as full_notes, (select count(*) from public.quizzes z join public.questions q on q.quiz_id=z.id where z.topic_id=t.id) as qs from public.topics t join public.subject_levels lvl on lvl.id=t.subject_level_id join public.subjects sub on sub.id=lvl.subject_id where (select count(*) from public.study_materials m where m.topic_id=t.id and m.material_type='notes' and length(m.content)>=1000)=0 or (select count(*) from public.quizzes z join public.questions q on q.quiz_id=z.id where z.topic_id=t.id)<16 order by qs;
